"""Canonical 14-week topic sequence. Lecture numbers refer to the supplied bilingual notes.

Each week is a dict:
  title, lectures, summary, python            – as before
  examples  – list of worked examples: {question, example, steps, edge, label?, figure?}
              figure: an int selects visuals.figure(key); a string is inline HTML; absent = no figure
  objectives – 3–5 measurable statements ("By the end of this week you can…")
  scope      – examinable topics; "(reading only)" marks material that is read but not examined
  code       – optional: an int selects visuals.CODES[key]; a string is the Python demonstration itself
Helpers `title(n)`, `lectures(n)` and `WEEK_TUPLES` keep older callers working.
"""

def ex(question,example,steps,edge,label=None,figure=None):
 d={'question':question,'example':example,'steps':steps,'edge':edge}
 if label:d['label']=label
 if figure is not None:d['figure']=figure
 return d

